const ROUTES = W.ROUTES;
function adventureRoute(s) { return s.adventure?.route || 'forest'; }
function encounters(s) { return ROUTES[adventureRoute(s)]?.encounters || ENCOUNTERS; }
function currentEncounter(s) { return s.adventure ? encounters(s)[s.adventure.step] || null : null; }
function previewChoice(s, choice) {
  const c = s.creatures.find(c => c.id === s.adventure?.petId), e = currentEncounter(s);
  if (!c || !e || ![0, 1].includes(choice)) return null;
  const option = e.choices[choice], success = c[option.ability] >= option.threshold;
  return {ability: option.ability, value: c[option.ability], threshold: option.threshold,
    success, coins: success ? option.coins : Math.round(option.coins * .55), xp: option.xp};
}
function visitedRoutes(c) {
  // Before v0.9 all completed journeys were in the original forest. Preserve that progress.
  return c.trails ? [...c.trails] : c.memory.adventure > 0 ? ['forest'] : [];
}

/* v0.9: original trail cards and legible, bounded personality feedback. */
.route-list{display:grid;gap:12px;margin:16px 0}.route-option{display:grid;grid-template-columns:78px 1fr 12px;align-items:center;gap:12px;width:100%;min-height:128px;padding:14px;text-align:left;border:1px solid #c9d5bd;border-radius:17px;background:#f0f3e6}.route-art{width:100%;height:70px;border-radius:12px;object-fit:cover}.route-description{display:grid;gap:6px;min-width:0}.route-description>strong{font-size:16px;color:#294b35}.route-description>span{font-size:12px;color:#4b6045}.route-description small{font-size:11px;color:#506040}.route-description strong small{display:inline-block;padding:1px 5px;background:#e1e9d4;border-radius:6px}.route-note{font-size:12px}.choice-outlook{padding-top:7px;border-top:1px solid #d0d9c0;line-height:1.75;color:#354d32!important}.trail-collection{padding:20px;margin-bottom:18px}.trail-collection>p{font-size:12px;margin:8px 0}.trail-stamps{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:16px 0}.trail-stamp{display:grid;justify-items:center;gap:7px;padding:12px 5px;border:1px dashed #9ba991;border-radius:14px;background:#f2f1e8}.trail-stamp.visited{background:#e6efd9;border:1px solid #9eb787}.trail-stamp .icon{width:28px;height:28px}.trail-stamp strong{font-size:12px}.trail-stamp span{font-size:11px;color:#4e6146}.temperament-note{padding:16px;background:#eff2e4;border:1px solid #d5dfc7;border-radius:15px;margin:12px 0}.temperament-note strong{display:block;font-size:14px;margin:6px 0}.temperament-note p{font-size:13px}.temperament-note small{display:block;margin-top:10px;line-height:1.7;color:#53634b}
.pet-actor[data-temperament="curiosity"]{animation:curious-idle 5s ease-in-out infinite}.pet-actor[data-temperament="courage"]{animation:confident-idle 4.5s ease-in-out infinite}.pet-actor[data-temperament="emotionalStability"]{animation-duration:6.5s}.pet-actor.mood-feed{animation:munch .65s ease 2}.pet-actor.mood-bath{animation:wiggle .8s ease 2}.pet-actor.mood-talk{animation:hop .8s ease 2}.pet-actor.sick,.pet-actor.dead{animation:none}
@keyframes curious-idle{0%,65%,100%{transform:translateX(-50%)}35%{transform:translateX(-50%) rotate(3deg)}}@keyframes confident-idle{0%,100%{transform:translateX(-50%)}50%{transform:translateX(-50%) scale(1.015,1.025)}}
@media(min-width:760px){.route-list{grid-template-columns:repeat(2,minmax(0,1fr))}.route-option{grid-template-columns:1fr 12px;align-content:start;min-height:250px;gap:10px}.route-art{grid-column:1/-1;height:86px}.trail-stamps{grid-template-columns:repeat(4,minmax(0,1fr))}}
@media(max-width:350px){.route-option{grid-template-columns:55px 1fr 10px;padding:12px;gap:9px}.route-description>strong{font-size:14px}.route-description>span{font-size:11px}.route-description small{font-size:10px}.trail-collection{padding:16px}}
@media(prefers-reduced-motion:reduce){.pet-actor{animation:none!important;transform:translateX(-50%)!important}}
/* Show the complete short reply; clipping a character's words is not an acceptable small-screen fallback. */
.pet-speech{width:min(78%,310px);max-height:none}
@media(max-height:700px) and (max-width:759px){.pet-speech{width:calc(100% - 88px);max-height:none}}

// Independent real UI session: finish every route, preserve per-pet stamps and inspect choices.
const trailsContext=await browser.newContext({viewport:{width:320,height:568},isMobile:true,hasTouch:true,reducedMotion:'reduce'});
const trails=await trailsContext.newPage();trails.on('pageerror',e=>errors.push(e.message));await trails.goto(BASE);await trails.locator('[data-start="demo"]').click();
const trailClick=action=>trails.locator(`[data-action="${action}"]`).first().click();
for(const route of ['forest','meadow','brook','ridge']){
  await trailClick('feed');await trailClick('bath');
  await trails.locator('.nav-button[data-view="explore"]').click();await trailClick('adventure');
  assert.equal(await trails.locator('[data-route]').count(),4);
  assert(await trails.locator('dialog').evaluate(d=>d.scrollWidth<=d.clientWidth),'route sheet overflow');
  if(route==='meadow'){
    await trails.addScriptTag({path:require.resolve('axe-core/axe.min.js')});
    const a11y=await trails.evaluate(async()=>{const r=await axe.run(document,{runOnly:{type:'tag',values:['wcag2a','wcag2aa','wcag21aa']}});return r.violations.map(v=>({id:v.id,impact:v.impact,nodes:v.nodes.map(n=>n.target)}));});
    await fs.writeFile(path.join(output,'route-accessibility.json'),JSON.stringify(a11y,null,2));assert.equal(a11y.filter(v=>['critical','serious'].includes(v.impact)).length,0,JSON.stringify(a11y));
    await trails.screenshot({path:path.join(output,'mobile-routes.png'),fullPage:false});
  }
  await trails.locator(`[data-route="${route}"]`).click();
  for(let step=0;step<3;step++){
    assert.equal(await trails.locator('.choice-outlook').count(),2);
    const current=await trails.evaluate(()=>{const s=JSON.parse(localStorage.getItem('forest-child-mvp-v2-demo'));return{preview:ForestGame.previewChoice(s,0),coins:s.adventure.coins,route:s.adventure.route};});
    assert.equal(current.route,route);assert((await trails.locator('.choice-outlook').first().innerText()).includes(`${current.preview.coins} G`));
    await trails.locator('[data-choice="0"]').click();
    assert.equal(await trails.evaluate(()=>JSON.parse(localStorage.getItem('forest-child-mvp-v2-demo')).adventure.coins),current.coins+current.preview.coins);
    if(step===0){await trailClick('close');await trails.reload();await trails.locator('.nav-button[data-view="explore"]').click();await trailClick('adventure');assert.equal(await trails.locator('[data-route]').count(),0);}
  }
  await trailClick('finish-adventure');await trails.locator('.nav-button[data-view="explore"]').click();
  assert(await trails.locator('[data-action="adventure"]').isDisabled(),'day allowance spans every route');
  await trails.locator('.nav-button[data-view="home"]').click();await trailClick('next-day');
}
await trails.locator('.nav-button[data-view="journal"]').click();assert.equal(await trails.locator('.trail-stamp.visited').count(),4);await trails.screenshot({path:path.join(output,'mobile-trail-journal.png'),fullPage:true});
await trails.reload();await trails.locator('.nav-button[data-view="journal"]').click();assert.equal(await trails.locator('.trail-stamp.visited').count(),4);
await trails.locator('.nav-button[data-view="home"]').click();await trailClick('pet');const reply=await trails.locator('.pet-speech').innerText();
assert(reply.length>0);await trailClick('profile');assert(await trails.locator('.temperament-note').isVisible());
await trailsContext.close();check('four routes, legible selector, honest outcome previews, resumable trips and per-pet travel journal');
